#!/bin/bash
whois "$1" | awk -F': +' 'BEGIN{split("Registrant Name,Registrant Organization,Registrant Street,Registrant City,Registrant State/Province,Registrant Postal Code,Registrant Country,Registrant Phone,Registrant Phone Ext:,Registrant Fax,Registrant Fax Ext:,Registrant Email,Admin Name,Admin Organization,Admin Street,Admin City,Admin State/Province,Admin Postal Code,Admin Country,Admin Phone,Admin Phone Ext:,Admin Fax,Admin Fax Ext:,Admin Email,Tech Name,Tech Organization,Tech Street,Tech City,Tech State/Province,Tech Postal Code,Tech Country,Tech Phone,Tech Phone Ext:,Tech Fax,Tech Fax Ext:,Tech Email",f,",")}{k=$1; v=$2; gsub(/^[ \t]+|[ \t]+$/, "", k); gsub(/^[ \t]+|[ \t]+$/, "", v); if(k!="") d[k]=v} END{for(i=1;i<=36;i++){val=d[f[i]]; if(f[i] ~ /Street$/ && val!="") val=val " "; printf "%s,%s%s", f[i], val, (i<36 ? ORS : "")}}' > "$1.csv"
